<?php
$escape = function ($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); };
$selectedProduct = !empty($item->product_id) ? ($item->product_title_ru ?: $item->product_title_ro) . ' (#' . (int) $item->product_id . ')' : '';
?>
<div class="page-bar"><ul class="page-breadcrumb"><li><i class="fa fa-home"></i> <a href="/<?= ADM_CONTROLLER ?>/menu/">Главная</a> <i class="fa fa-circle"></i></li><li><a href="<?= $escape($parent_url) ?>"><?= $escape($parent_title) ?></a> <i class="fa fa-circle"></i></li><li><span><?= $escape($title) ?></span></li></ul></div>
<h1 class="page-title"><?= $escape($title) ?></h1>
<?php if (isset($_SESSION['success'])) : ?><div class="alert alert-success"><?= $escape($_SESSION['success']); unset($_SESSION['success']); ?></div><?php endif; ?>
<?php if (isset($_SESSION['error'])) : ?><div class="alert alert-danger"><?php foreach ((array) $_SESSION['error'] as $error) echo $escape($error) . '<br>'; unset($_SESSION['error']); ?></div><?php endif; ?>
<div class="row"><div class="portlet light"><div class="portlet-body"><form method="post"><div class="panel-body">
    <?php foreach (array('RU', 'RO') as $lang) : ?><div class="form-group"><label>Название <?= $lang ?> *</label><input class="form-control" name="title<?= $lang ?>" maxlength="255" required value="<?= $escape($item->{'title' . $lang}) ?>"></div><div class="form-group"><label>Описание <?= $lang ?></label><textarea class="form-control" name="description<?= $lang ?>" rows="2"><?= $escape($item->{'description' . $lang}) ?></textarea></div><?php endforeach; ?>
    <div class="form-group"><label>Товар подарка *</label><div class="gift-product-picker" data-lookup="<?= $escape($parent_url) ?>product_lookup" data-variants="<?= $escape($parent_url) ?>variant_lookup/"><input class="form-control" type="search" data-product-search placeholder="Найти товар по названию, артикулу или ID" value="<?= $escape($selectedProduct) ?>"><div data-product-results style="margin-top:8px"></div><div data-product-selected style="margin-top:8px;color:#333"><?= $escape($selectedProduct) ?></div><input type="hidden" name="product_id" data-product-id value="<?= (int) $item->product_id ?>" required><select class="form-control" name="variant_id" data-variant style="margin-top:8px"><option value="">Весь товар / без варианта</option><?php foreach ($variants as $variant) : ?><option value="<?= (int) $variant->id ?>" <?= (int) $variant->id === (int) $item->variant_id ? 'selected' : '' ?>>#<?= (int) $variant->id ?> <?= $escape($variant->titleRU ?: $variant->titleRO ?: $variant->SKU) ?></option><?php endforeach; ?></select></div></div>
    <div class="form-group"><label>Порядок</label><input class="form-control" type="number" name="sorder" value="<?= (int) $item->sorder ?>" style="max-width:120px"></div><label class="mt-checkbox mt-checkbox-outline"><input type="checkbox" name="is_enabled" value="1" <?= !empty($item->is_enabled) ? 'checked' : '' ?>> Активен<span></span></label><br><label class="mt-checkbox mt-checkbox-outline"><input type="checkbox" name="show_on_site" value="1" <?= !empty($item->show_on_site) ? 'checked' : '' ?>> Показывать на сайте<span></span></label>
    <p><button class="btn green" type="submit"><i class="fa fa-check"></i> Сохранить</button> <a class="btn default" href="<?= $escape($parent_url) ?>">Назад</a></p>
</div></form></div></div></div>
<script>
(function () { var root = document.querySelector('.gift-product-picker'); if (!root) return; var input = root.querySelector('[data-product-search]'), results = root.querySelector('[data-product-results]'), selected = root.querySelector('[data-product-selected]'), productId = root.querySelector('[data-product-id]'), variant = root.querySelector('[data-variant]'); function loadVariants(id) { variant.innerHTML = '<option value="">Весь товар / без варианта</option>'; if (!id) return; fetch(root.dataset.variants + encodeURIComponent(id)).then(function (r) { return r.json(); }).then(function (list) { list.forEach(function (v) { var o = document.createElement('option'); o.value = v.id; o.textContent = '#' + v.id + ' ' + (v.titleRU || v.titleRO || v.SKU || 'Вариант'); variant.appendChild(o); }); }); } function choose(p) { productId.value = p.id; selected.textContent = (p.titleRU || p.titleRO || 'Товар') + ' (#' + p.id + ')'; input.value = ''; results.innerHTML = ''; loadVariants(p.id); } input.addEventListener('input', function () { var q = input.value.trim(); if (q.length < 2) { results.innerHTML = ''; return; } fetch(root.dataset.lookup + '?q=' + encodeURIComponent(q)).then(function (r) { return r.json(); }).then(function (list) { results.innerHTML = list.map(function (p) { return '<button type="button" class="btn btn-xs default" data-id="' + p.id + '" style="margin:0 5px 5px 0">' + (p.titleRU || p.titleRO || 'Товар') + ' (#' + p.id + ')</button>'; }).join(''); results.querySelectorAll('[data-id]').forEach(function (button) { button.onclick = function () { choose(list.find(function (p) { return String(p.id) === button.dataset.id; })); }; }); }); }); }());
</script>
